const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const lon = 49.357405;
    const lat = 39.014501;
    const aoi = ee.Geometry.Point([lon, lat]).buffer(4000); // 4 km radius
    const dateA = '2022-11-19';
    const dateB = '2023-02-13';
    const scale = 1000; // per requirement
    const existThreshold = 10000; // m2 threshold to consider an island exists
    const noneThreshold = 3000;   // m2 threshold to consider no island

    // 2. Masking and preparation helpers
    function maskS2(img) {
      const qa = img.select('QA60');
      const mask = qa.bitwiseAnd(1 << 10).eq(0).and(qa.bitwiseAnd(1 << 11).eq(0));
      // Select green (B3) and swir1 (B11). Scale not required for normalizedDifference.
      return img.updateMask(mask).select(['B3', 'B11'], ['green', 'swir1']).toFloat();
    }
    function maskLandsatL2(img) {
      const qa = img.select('QA_PIXEL');
      const mask = qa.bitwiseAnd(1 << 3).eq(0).and(qa.bitwiseAnd(1 << 4).eq(0)); // cloud & shadow
      const sr = img.select(['SR_B3', 'SR_B6']).multiply(0.0000275).add(-0.2).rename(['green', 'swir1']).toFloat();
      return sr.updateMask(mask);
    }

    function tryCollections(start, end, region) {
      // Returns: {img, src, count, usedStart, usedEnd}
      const sources = [
        {id: 'COPERNICUS/S2_SR', prep: maskS2, sortProp: 'CLOUDY_PIXEL_PERCENTAGE', src: 'S2_SR'},
        {id: 'LANDSAT/LC09/C02/T1_L2', prep: maskLandsatL2, sortProp: 'CLOUD_COVER', src: 'Landsat9_L2'},
        {id: 'LANDSAT/LC08/C02/T1_L2', prep: maskLandsatL2, sortProp: 'CLOUD_COVER', src: 'Landsat8_L2'}
      ];
      for (let i = 0; i < sources.length; i++) {
        const s = sources[i];
        let col = ee.ImageCollection(s.id).filterBounds(region).filterDate(start, end);
        // Light cloud filter where available
        if (s.src === 'S2_SR') col = col.filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 80));
        if (s.src !== 'S2_SR') col = col.filter(ee.Filter.lt('CLOUD_COVER', 80));
        col = col.sort(s.sortProp, true);
        const count = col.size().getInfo();
        if (count > 0) {
          const raw = ee.Image(col.first());
          const img = s.prep(raw);
          const used = {
            img: img,
            src: s.src,
            count: count,
            usedStart: start,
            usedEnd: end,
            dateSelected: ee.Date(raw.get('system:time_start')).format('YYYY-MM-dd').getInfo()
          };
          return used;
        }
      }
      return null;
    }

    function getBestImageForDate(dateStr, region) {
      // Try exact day [d, d+1)
      const d = ee.Date(dateStr);
      let res = tryCollections(d, d.advance(1, 'day'), region);
      if (res) { res.window = '±0d'; return res; }
      // Try widened window ±3 days
      res = tryCollections(d.advance(-3, 'day'), d.advance(4, 'day'), region);
      if (res) { res.window = '±3d'; return res; }
      return null;
    }

    function analyze(dateStr) {
      const best = getBestImageForDate(dateStr, aoi);
      if (!best) {
        console.log(`${dateStr}: No images found in S2/L9/L8 (±3d).`);
        return {code: 'C1'};
      }
      const ndwi = best.img.normalizedDifference(['green', 'swir1']).rename('ndwi');
      // Counts
      const totalCount = ee.Image.constant(1).rename('ones').reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: aoi,
        scale: scale,
        maxPixels: 1e9
      }).get('ones');
      const validCount = ndwi.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: aoi,
        scale: scale,
        maxPixels: 1e9
      }).get('ndwi');
      const total = ee.Number(totalCount).getInfo();
      const valid = ee.Number(validCount).getInfo();
      if (total === null || valid === null) {
        console.log(`${dateStr}: Calculation returned null counts.`);
        return {code: 'C3'};
      }
      if (valid === 0) {
        console.log(`${dateStr}: No valid pixels after masking.`);
        return {code: 'C2'};
      }
      const cloudPct = (1 - (valid / total)) * 100.0;
      const landArea = ee.Image.pixelArea().updateMask(ndwi.lt(0)).reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: aoi,
        scale: scale,
        maxPixels: 1e9
      }).get('area');
      const landAreaM2 = landArea ? ee.Number(landArea).getInfo() : null;
      if (landAreaM2 === null || isNaN(landAreaM2)) {
        console.log(`${dateStr}: Area calculation failed.`);
        return {code: 'C3'};
      }
      // Print concise line
      console.log(`${dateStr} -> Used: ${best.dateSelected} ${best.src} (${best.window}), imgs: ${best.count}, valid px: ${valid}/${total} (cloud: ${cloudPct.toFixed(1)}%), land: ${Math.round(landAreaM2)} m2`);
      return {code: 'OK', landAreaM2: landAreaM2};
    }

    const resA = analyze(dateA);
    if (resA.code !== 'OK') { console.log(resA.code); return; }
    const resB = analyze(dateB);
    if (resB.code !== 'OK') { console.log(resB.code); return; }

    const delta = resB.landAreaM2 - resA.landAreaM2;
    console.log(`Δ land (2023-02-13 minus 2022-11-19): ${Math.round(delta)} m2`);

    // 5. Validation & Final Answer
    if (resA.landAreaM2 === null || resB.landAreaM2 === null || isNaN(resA.landAreaM2) || isNaN(resB.landAreaM2)) {
      console.log('C3');
      return;
    }
    const appeared = (resA.landAreaM2 < noneThreshold) && (resB.landAreaM2 >= existThreshold);
    console.log(appeared ? 'A' : 'B');
  } catch (e) {
    // Any unexpected error
    console.log(`Error: ${e && e.message ? e.message : e}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
